rows = 7
cols = 18

grid = [[9]*cols for _ in range(rows)]
positions = []

# r - c = 4 main diagonal
for r in range(rows):
    for c in range(cols):
        if r - c == 4:
            positions.append((r, c))

# r + c = 6 anti diagonal  
for r in range(rows):
    for c in range(cols):
        if r + c == 6:
            positions.append((r, c))

positions = list(set(positions))
for (r, c) in positions:
    grid[r][c] = 1

print(f"X pattern grid: {len(positions)} cells at {positions}")
print("\nGrid visualization:")
for row in grid:
    print(" ".join(str(x) for x in row))

